/**
 * The Compilers section's shared panel: C on the left, what a tool made of it on the right (assembly, or the
 * preprocessor's output), with each source line and its output drawn in the same colour. Click a line on either side
 * to pick it out; the status line says what each instruction does. The listings are real Clang output from
 * `ccdata.ts`, generated by scripts/ccgen.ts.
 */
import { esc } from '../core/render';
import { highlight } from './dbg';

export interface Out { t: string; src: number; kind: 'label' | 'ins' | 'data' | 'pad' | 'text' | 'from'; hex?: string; n?: number }

// ---- what each instruction does ------------------------------------------------------------------------------------

const COND: Record<string, string> = {
  eq: 'the two were equal (Z = 1)', ne: 'the two were not equal (Z = 0)',
  lt: 'the first was less, as signed numbers', ge: 'the first was greater or equal, as signed numbers',
  gt: 'the first was greater, as signed numbers', le: 'the first was less or equal, as signed numbers',
  hs: 'the first was higher or the same, as unsigned numbers', lo: 'the first was lower, as unsigned numbers',
  hi: 'the first was higher, as unsigned numbers', ls: 'the first was lower or the same, as unsigned numbers',
  mi: 'the result’s top bit was 1 (N = 1)', pl: 'the result’s top bit was 0 (N = 0)',
};
const OP: Record<string, string> = { adds: '+', subs: '−', ands: '&', orrs: '|', eors: '^', lsls: '<<', lsrs: '>>', asrs: '>>' };
const regs = (list: string) => list.replace(/[{}]/g, '').split(/,\s*/);
const and = (xs: string[]) => (xs.length < 2 ? xs.join('') : `${xs.slice(0, -1).join(', ')} and ${xs[xs.length - 1]}`);
const num = (s: string) => s.replace(/^#/, '');
const label = (s: string) => (s.startsWith('.LBB') ? `the label ${s}` : s);

/** One plain sentence for a Thumb instruction or literal-pool word, or null if it is not one the pages use. */
export function explainIns(line: string, kind: Out['kind'] = 'ins'): string | null {
  if (kind === 'pad') return 'Padding, so the 32-bit constant after it starts on a 4-byte boundary. It never runs.';
  if (kind === 'data') {
    const v = line.replace(/^\.word\s+/, '');
    return /^0x/.test(v)
      ? `A 32-bit constant, ${v}, stored after the code. A 16-bit instruction has no room for it, so ldr loads it from here.`
      : `The address of ${v}, stored after the code. The linker writes it in once it knows where ${v} lives.`;
  }
  const [op, rest = ''] = [line.split(' ')[0], line.slice(line.indexOf(' ') + 1)];
  const a = rest.split(/,\s*(?![^[{]*[\]}])/);
  const mem = (s: string) => {
    const m = s.match(/^\[(\w+)(?:,\s*(#?[-\w]+))?\]$/);
    if (!m) return s;
    if (m[1] === 'sp') return `the stack, ${m[2] ? `${num(m[2])} bytes above sp` : 'at sp'} (a local variable)`;
    return m[2] ? `the address ${m[1]} + ${num(m[2])}` : `the address in ${m[1]}`;
  };
  switch (op) {
    case 'movs': return `${a[0]} = ${num(a[1])}.`;
    case 'mov': return `Copy ${a[1]} into ${a[0]}.`;
    case 'mvns': return `${a[0]} = ~${a[1]}: every bit flipped.`;
    case 'add': case 'sub':
      if (a[0] === 'sp') return op === 'sub' ? `Make room for ${num(a[1])} bytes of local variables on the stack.` : `Give back the ${num(a[1])} bytes of stack the locals used.`;
      return null;
    case 'adds': case 'subs': case 'ands': case 'orrs': case 'eors': case 'lsls': case 'lsrs': case 'asrs': {
      const [d, x, y] = a.length === 3 ? a : [a[0], a[0], a[1]];
      const shift = op === 'lsrs' ? ', filling with zeros' : op === 'asrs' ? ', copying the sign bit in' : '';
      return `${d} = ${x} ${OP[op]} ${num(y)}${shift}, and set the flags.`;
    }
    case 'adcs': return `${a[0]} = ${a[0]} + ${a[1]} + the carry flag.`;
    case 'sbcs': return `${a[0]} = ${a[0]} − ${a[1]} − 1 + the carry flag (a subtract with borrow).`;
    case 'rsbs': return `${a[0]} = 0 − ${a[1]}, and set the carry flag if ${a[1]} was 0.`;
    case 'muls': return `${a[0]} = ${a[1]} × ${a[2]}.`;
    case 'cmp': return `Compare ${a[0]} with ${num(a[1])}: work out ${a[0]} − ${num(a[1])} and keep only the flags.`;
    case 'b': return `Jump to ${label(a[0])}.`;
    case 'bl': return `Call ${a[0]}: jump to it, with the return address in lr.`;
    case 'bx': return a[0] === 'lr' ? 'Return to the caller: jump to the address in lr.' : `Jump to the address in ${a[0]}.`;
    case 'push': {
      const r = regs(rest);
      return `Save ${and(r)} on the stack${r.includes('lr') ? ', so this function can call another and still return' : ''}.`;
    }
    case 'pop': {
      const r = regs(rest);
      return r.includes('pc') ? `Restore ${and(r.filter((x) => x !== 'pc'))}, and return by loading the saved lr into pc.` : `Restore ${and(r)}.`;
    }
    case 'ldr':
      if (a[1].startsWith('.LCPI')) return `Load the 32-bit constant at ${a[1]}, after the code, into ${a[0]}.`;
      if (/^\[\w+, \w+\]$/.test(a[1])) { const [, b, i] = a[1].match(/\[(\w+), (\w+)\]/)!; return `Load the word at the address ${b} + ${i} into ${a[0]}.`; }
      return `Load the 32-bit word from ${mem(a[1])} into ${a[0]}.`;
    case 'ldrb': return `Load one byte from ${mem(a[1])} into ${a[0]}.`;
    case 'str': return `Store ${a[0]} to ${mem(a[1])}.`;
    case 'ldm': {
      const m = rest.match(/^(\w+)!, \{(\w+)\}$/);
      return m ? `Load ${m[2]} from the address in ${m[1]}, then add 4 to ${m[1]}: the next element.` : null;
    }
  }
  const c = op.match(/^b(eq|ne|lt|ge|gt|le|hs|lo|hi|ls|mi|pl)$/);
  if (c) return `Jump to ${label(a[0])} if ${COND[c[1]]}; otherwise carry on.`;
  return null;
}

// ---- the panel ---------------------------------------------------------------------------------------------------

/** The panel's frame: the controls in the bar, two panes, and the status line. `rows` reserves each pane's height. */
export const explorerHtml = (o: { file: string; controls?: string; label: string; cls?: string }) => `
  <section class="debugger cc${o.cls ? ` ${o.cls}` : ''}" aria-label="${esc(o.label)}">
    <header class="dbg-bar">
      <span class="dbg-file">${esc(o.file)}</span>
      <div class="dbg-controls">${o.controls ?? ''}</div>
    </header>
    <div class="dbg-body cc-body">
      <div class="cc-pane"><p class="cc-head">${esc(o.file)}</p><pre class="dbg-code cc-src" aria-label="C source"><code></code></pre></div>
      <div class="cc-pane"><p class="cc-head cc-out-head"></p><pre class="dbg-code cc-out" aria-label="Output"><code></code></pre></div>
    </div>
    <p class="dbg-status cc-status" aria-live="polite"></p>
  </section>`;

export interface View {
  src: string;
  out: Out[];
  /** The right pane's heading, such as "led.s · -Os · 22 bytes". */
  head: string;
  /** What the status line says when nothing is picked. */
  summary: string;
  /** Whether to show each instruction's bytes. */
  hex?: boolean;
}

/**
 * Wires an explorer. `view()` gives what to show now; call the returned `draw()` after a control changes it.
 * `rows` is the most lines any view has on either side, so switching views never changes the panel's height.
 */
export function explorer(root: HTMLElement, rows: { src: number; out: number }, view: () => View, describe?: (o: Out) => string | null) {
  const panel = root.querySelector<HTMLElement>('.cc')!;
  // Side by side, both panes take the taller one's height; stacked on a phone, each keeps its own. Past 24 lines a
  // pane scrolls, so one long listing does not leave every other view mostly empty.
  const cap = (n: number) => String(Math.min(n, 24));
  panel.classList.add('sized');
  panel.style.setProperty('--src-rows', cap(rows.src));
  panel.style.setProperty('--out-rows', cap(rows.out));
  panel.style.setProperty('--rows', cap(Math.max(rows.src, rows.out)));
  let pick: { side: 'src' | 'out'; i: number } | null = null;
  const tell = (o: Out) => describe?.(o) ?? explainIns(o.t, o.kind);

  function draw(reset = false) {
    if (reset) pick = null;
    const v = view();
    const src = v.src.split('\n');
    // Each source line that produced output gets a colour, in order of first appearance.
    const colour = new Map<number, number>();
    for (const o of v.out) if (o.src && !colour.has(o.src)) colour.set(o.src, colour.size % 6);
    const line = pick?.side === 'src' ? pick.i : pick ? v.out[pick.i]?.src ?? 0 : 0;
    const on = (n: number) => (line && n === line ? ' on' : '');
    const c = (n: number) => (colour.has(n) ? ` c${colour.get(n)}` : '');

    panel.classList.toggle('picked', !!line);
    panel.querySelector('.cc-src code')!.innerHTML = src.map((t, k) =>
      `<span class="ln${c(k + 1)}${on(k + 1)}" data-src="${k + 1}"><span class="gutter">${k + 1}</span>${highlight(t) || ' '}</span>`).join('');
    panel.querySelector('.cc-out code')!.innerHTML = v.out.map((o, k) => {
      const body = o.kind === 'from'
        ? `<span class="cc-from">… ${o.n} lines from &lt;${esc(o.t)}&gt;</span>`
        : o.kind === 'text' ? highlight(o.t) || ' '
          : `${o.kind === 'label' ? '' : '    '}${esc(o.t)}`;
      const hex = v.hex ? `<span class="cc-hex">${esc(o.hex ?? '')}</span>` : '';
      const self = pick?.side === 'out' && pick.i === k ? ' self' : '';
      return `<span class="ln k-${o.kind}${c(o.src)}${on(o.src)}${self}" data-out="${k}">${hex}${body}</span>`;
    }).join('');
    panel.querySelector('.cc-out-head')!.innerHTML = v.head;
    // Bring the first matching line on the other side into view, scrolling only that pane, never the page.
    const other = panel.querySelector<HTMLElement>(pick?.side === 'src' ? '.cc-out' : '.cc-src');
    const first = other?.querySelector<HTMLElement>('.ln.on');
    if (pick && other && first && (first.offsetTop < other.scrollTop || first.offsetTop + first.offsetHeight > other.scrollTop + other.clientHeight))
      other.scrollTop = first.offsetTop - other.clientHeight / 3;
    if (reset) panel.querySelectorAll<HTMLElement>('.dbg-code').forEach((p) => (p.scrollTop = 0));

    let say = v.summary;
    if (pick?.side === 'out' && v.out[pick.i]) {
      const o = v.out[pick.i];
      const what = o.kind === 'label' ? (o.t.startsWith('.L') ? `A label the compiler made, for a branch or the constants to jump to or load.` : `The start of the function ${esc(o.t.replace(':', ''))}.`) : tell(o);
      say = `<code>${esc(o.t)}</code>: ${esc(what ?? '')}${o.src ? ` From line ${o.src}.` : ''}`;
    } else if (pick?.side === 'src') {
      const outs = v.out.filter((o) => o.src === pick!.i);
      const t = src[pick.i - 1].trim();
      say = !outs.length
        ? `Line ${pick.i}${t ? `, <code>${esc(t)}</code>,` : ''} produced nothing on the right.`
        : outs[0].kind === 'text' ? `Line ${pick.i} came out as ${outs.length === 1 ? 'one line' : `${outs.length} lines`}, highlighted on the right.`
          : `Line ${pick.i}, <code>${esc(t)}</code>, became ${outs.length === 1 ? 'one instruction' : `${outs.length} instructions`}, highlighted. Click one to see what it does.`;
    }
    panel.querySelector('.cc-status')!.innerHTML = say;
  }

  panel.addEventListener('click', (e) => {
    const l = (e.target as Element).closest<HTMLElement>('.ln');
    if (!l) return;
    const next = l.dataset.src ? { side: 'src' as const, i: Number(l.dataset.src) } : { side: 'out' as const, i: Number(l.dataset.out) };
    pick = pick && pick.side === next.side && pick.i === next.i ? null : next;
    draw();
  });
  draw();
  return { draw };
}

/** The listings use these kinds; a preprocessor line is plain text. */
export const asOut = (lines: readonly { t: string; src: number; kind: string; hex?: string }[]): Out[] =>
  lines.map((l) => ({ t: l.t, src: l.src, kind: l.kind as Out['kind'], hex: l.hex }));

/** "22 bytes · 11 instructions". */
export const sizeNote = (b: { bytes: number; ins: number }) => `${b.bytes} bytes · ${b.ins} instruction${b.ins === 1 ? '' : 's'}`;

/** The most lines any of these views needs on each side. */
export const maxRows = (views: { src: string; out: readonly unknown[] }[]) => ({
  src: Math.max(...views.map((v) => v.src.split('\n').length)),
  out: Math.max(...views.map((v) => v.out.length)),
});
